class QuickCaptureScreen extends StatefulWidget {
  const QuickCaptureScreen({super.key,required this.repository});
  final LifeosRepository repository;
  @override State<QuickCaptureScreen> createState()=>_QuickCaptureScreenState();
}
class _QuickCaptureScreenState extends State<QuickCaptureScreen> {
  final _captures=QuickCaptureRepository(); final _projects=ProjectRepository(); final _search=TextEditingController();
