  void _toast(String text)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(text)));
  Future<DateTime?> _pickDateTime(DateTime? initial)async{final now=DateTime.now();final date=await showDatePicker(context:context,initialDate:initial??now,firstDate:DateTime(now.year-1),lastDate:DateTime(now.year+10));if(date==null||!mounted)return null;final time=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(initial??now));if(time==null)return null;return DateTime(date.year,date.month,date.day,time.hour,time.minute);}
  Future<void> _edit([QuickCapture? item])async{
