    String kind=item?.kind??'task';DateTime? due=item?.dueAt,reminder=item?.reminderAt,scheduled=item?.scheduledAt;int reminderMinutes=item?.reminderMinutes??15;int? projectId=item?.projectId;
    final projects=await _projects.getProjects();if(!mounted){title.dispose();body.dispose();return;}
    final draft=await showModalBottomSheet<_CaptureDraft>(context:context,isScrollControlled:true,showDragHandle:true,builder:(context)=>StatefulBuilder(builder:(context,setSheet)=>Padding(padding:EdgeInsets.fromLTRB(20,8,20,MediaQuery.of(context).viewInsets.bottom+24),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,mainAxisSize:MainAxisSize.min,children:[
      Text(item==null?'Capture something':'Edit capture',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),
      SegmentedButton<String>(segments:const [ButtonSegment(value:'task',label:Text('Task'),icon:Icon(Icons.check_circle_outline)),ButtonSegment(value:'note',label:Text('Note'),icon:Icon(Icons.lightbulb_outline)),ButtonSegment(value:'event',label:Text('Event'),icon:Icon(Icons.event_outlined))],selected:{kind},onSelectionChanged:(v)=>setSheet(()=>kind=v.first)),const SizedBox(height:14),
