    title.dispose();body.dispose();
  }
  Future<void> _convert(QuickCapture item)async{try{if(item.kind=='task'){final id=await _captures.convertToTask(item);if(item.reminderAt!=null&&item.reminderAt!.isAfter(DateTime.now()))await ReminderService.instance.schedule(id:id,title:item.title,body:item.body.isEmpty?'LifeOS task reminder':item.body,at:item.reminderAt!);}else if(item.kind=='note'){await _captures.convertToNote(item);}else{final id=await _captures.convertToEvent(item);if(item.reminderMinutes>0){final at=item.scheduledAt!.subtract(Duration(minutes:item.reminderMinutes));if(at.isAfter(DateTime.now()))await ReminderService.instance.schedule(id:700000+id,title:item.title,body:'Upcoming event',at:at);}}await _refresh();_toast('Converted into ${item.kind=='note'?'a Second Brain note':item.kind=='event'?'a Planner event':'a task'}');}catch(e){_toast('Conversion failed: $e');}}
