    Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:Row(children:[Expanded(child:SegmentedButton<String>(segments:const [ButtonSegment(value:'inbox',label:Text('Inbox')),ButtonSegment(value:'processed',label:Text('Done')),ButtonSegment(value:'archived',label:Text('Archive'))],selected:{_status},onSelectionChanged:(v)=>setState((){_status=v.first;_load();}))),])),
    SizedBox(height:48,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:16,vertical:5),children:[for(final k in ['all','task','note','event'])Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(k=='all'?'All':k[0].toUpperCase()+k.substring(1)),selected:_kind==k,onSelected:(_)=>setState((){_kind=k;_load();}))) ])),
    Expanded(child:FutureBuilder<List<QuickCapture>>(future:_items,builder:(context,s){if(s.hasError)return Center(child:Text('Could not load captures: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final rows=s.data!;if(rows.isEmpty)return Center(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.inbox_outlined,size:52,color:Color(0xFF4567D7)),const SizedBox(height:12),Text(_status=='inbox'?'Your inbox is clear':'Nothing here yet',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('Capture a thought now. Decide where it belongs later.',textAlign:TextAlign.center,style:TextStyle(color:Colors.black54))])));return RefreshIndicator(onRefresh:_refresh,child:ListView.separated(padding:const EdgeInsets.fromLTRB(16,4,16,100),itemCount:rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(context,i){final item=rows[i];final icon=item.kind=='task'?Icons.check_circle_outline:item.kind=='note'?Icons.lightbulb_outline:Icons.event_outlined;return Card(child:ListTile(leading:CircleAvatar(backgroundColor:const Color(0xFFEAF0FF),child:Icon(icon,color:const Color(0xFF315FE7))),title:Text(item.title,style:const TextStyle(fontWeight:FontWeight.w800),maxLines:2,overflow:TextOverflow.ellipsis),subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(item.body.isNotEmpty)Text(item.body,maxLines:2,overflow:TextOverflow.ellipsis),Text(item.kind=='task'?(item.dueAt==null?'Task': 'Due ${_date(item.dueAt!)}'):item.kind=='event'?'Starts ${_date(item.scheduledAt!)}':'Second Brain note',style:const TextStyle(fontSize:11,color:Color(0xFF718096))),if(item.convertedType!=null)Text('Created as ${item.convertedType} #${item.convertedId}',style:const TextStyle(fontSize:11,color:Colors.green))]),isThreeLine:item.body.isNotEmpty,trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit')await _edit(item);if(v=='convert')await _convert(item);if(v=='archive'){await _captures.setStatus(item.id,'archived');await _refresh();}if(v=='restore'){await _captures.setStatus(item.id,'inbox');await _refresh();}if(v=='delete'){await _captures.deleteCapture(item.id);await _refresh();}},itemBuilder:(_)=>[if(item.status=='inbox')... [const PopupMenuItem(value:'edit',child:Text('Edit')),const PopupMenuItem(value:'convert',child:Text('Convert to LifeOS')),const PopupMenuItem(value:'archive',child:Text('Archive'))],if(item.status=='archived')const PopupMenuItem(value:'restore',child:Text('Restore')),const PopupMenuItem(value:'delete',child:Text('Delete'))]))); }));}))
  ]));
}
